package com.siam.vault;

import android.app.AlertDialog;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.view.Gravity;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import com.siam.vault.database.AppDatabase;
import com.siam.vault.helper.FileHelper;
import com.siam.vault.helper.Ui;
import java.io.File;
import java.util.*;

public class VideoActivity extends AppCompatActivity {
    private AppDatabase db;private LinearLayout list;private File playing;private boolean bin;
    @Override protected void onCreate(Bundle b){super.onCreate(b);Ui.secure(this);db=new AppDatabase(this);bin=getIntent().getBooleanExtra("bin",false);if(bin){long cutoff=System.currentTimeMillis()-30L*24*60*60*1000;for(AppDatabase.Media m:db.expiredRecycleItems(cutoff)){FileHelper.deleteVaultFile(m);db.remove(m.id);}}render();}
    private void render(){LinearLayout root=Ui.column(this);LinearLayout top=Ui.row(this);top.addView(Ui.chip(this,"Back",this::finish));top.addView(Ui.text(this,bin?"Video Recycle Bin":"Videos",24,true));Ui.add(root,top,-2);if(!bin)Ui.add(root,Ui.button(this,"ভিডিও Import করুন",this::pick),52);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);load();}
    private void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("video/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,51);}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==51&&result==RESULT_OK&&data!=null){ArrayList<Uri> uris=new ArrayList<>(),imported=new ArrayList<>();if(data.getClipData()!=null){for(int x=0;x<data.getClipData().getItemCount();x++)uris.add(data.getClipData().getItemAt(x).getUri());}else if(data.getData()!=null)uris.add(data.getData());int ok=0;for(Uri u:uris)try{FileHelper.importUri(this,u,"video","ভিডিও");ok++;imported.add(u);}catch(Exception ignored){}Toast.makeText(this,ok+"টি ভিডিও encrypted হয়েছে",Toast.LENGTH_LONG).show();load();if(!imported.isEmpty())new AlertDialog.Builder(this).setTitle("Gallery থেকে Delete করবেন?").setMessage("Import সফল হয়েছে। নির্বাচিত original ভিডিও মুছতে চাইলে Delete চাপুন; provider অনুমতি না দিলে Gallery থেকে নিজে মুছুন।").setNegativeButton("রেখে দিন",null).setPositiveButton("Delete originals",(d,w)->{int count=0;for(Uri u:imported)try{count+=getContentResolver().delete(u,null,null);}catch(Exception ignored){}Toast.makeText(this,count>0?count+"টি original মুছে গেছে":"এই provider delete করতে দেয়নি — Gallery থেকে নিজে মুছুন",Toast.LENGTH_LONG).show();}).show();}}
    private void load(){list.removeAllViews();for(AppDatabase.Media m:db.media("video",bin,null)){LinearLayout row=Ui.row(this);ImageView play=new ImageView(this);play.setImageResource(R.drawable.ic_video);play.setContentDescription("Play video");row.addView(play,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,56)));LinearLayout labels=new LinearLayout(this);labels.setOrientation(LinearLayout.VERTICAL);TextView name=Ui.text(this,m.name,16,true);TextView size=Ui.text(this,String.format(Locale.US,"%.1f MB",m.size/(1024f*1024f)),12,false);size.setTextColor(Ui.GREY);labels.addView(name);labels.addView(size);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));TextView more=Ui.chip(this,"Options",()->actions(m));row.addView(more);play.setOnClickListener(v->{if(bin)actions(m);else play(m);});row.setOnClickListener(v->{if(bin)actions(m);else play(m);});Ui.card(list,row);}}
    private void play(AppDatabase.Media m){try{playing=FileHelper.decryptToCache(this,m);VideoView vv=new VideoView(this);vv.setVideoPath(playing.getAbsolutePath());MediaController controls=new MediaController(this);controls.setAnchorView(vv);vv.setMediaController(controls);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(m.name).setView(vv).setNegativeButton("বন্ধ",(d,w)->vv.stopPlayback()).create();dialog.setOnDismissListener(d->{vv.stopPlayback();if(playing!=null){playing.delete();playing=null;}});dialog.show();vv.start();}catch(Exception e){Toast.makeText(this,"ভিডিও খোলা যায়নি",Toast.LENGTH_LONG).show();}}
    private void actions(AppDatabase.Media m){if(bin){new AlertDialog.Builder(this).setTitle(m.name).setItems(new String[]{"Restore to Vault","চিরতরে Delete"},(d,w)->{if(w==0)db.restore(m.id);else{FileHelper.deleteVaultFile(m);db.remove(m.id);}load();}).show();return;}new AlertDialog.Builder(this).setTitle(m.name).setItems(new String[]{"Recycle Bin-এ রাখুন","Gallery-তে ফিরিয়ে দিন","চিরতরে Delete"},(d,w)->{if(w==0){db.softDelete(m.id);load();}else if(w==1){new AlertDialog.Builder(this).setMessage("Gallery-তে কপি করে Vault-এর encrypted কপি মুছে ফেলা হবে।").setNegativeButton("Cancel",null).setPositiveButton("Restore",(x,y)->new Thread(()->{try{FileHelper.restoreToGallery(this,m);db.remove(m.id);new File(m.path).delete();runOnUiThread(this::load);}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Restore ব্যর্থ",Toast.LENGTH_SHORT).show());}}).start()).show();}else new AlertDialog.Builder(this).setMessage("ফেরানো যাবে না — নিশ্চিত?").setNegativeButton("Cancel",null).setPositiveButton("Delete",(x,y)->{FileHelper.deleteVaultFile(m);db.remove(m.id);load();}).show();}).show();}
    @Override protected void onDestroy(){if(playing!=null){playing.delete();playing=null;}super.onDestroy();}
}
